SELECT role_id, name, description, builtin, TO_CHAR(create_time, 'YYYY-MM-DD HH24:MI:SS') AS create_time, TO_CHAR(update_time, 'YYYY-MM-DD HH24:MI:SS') AS update_time FROM app_role WHERE role_id IN
#{roleId}
ORDER BY create_time, role_id

SELECT DISTINCT permission_code FROM role_permission WHERE role_id IN
#{roleId}
ORDER BY permission_code
